}

// Pop removes and returns the top element with ok=true, or 0, false when the
// stack is empty.
func (s *IntStack) Pop() (v int, ok bool) {
	if len(s.items) == 0 {
		return 0, false
	}
	i := len(s.items) - 1
	v = s.items[i]
	s.items[i] = 0
	s.items = s.items[:i]
	return v, true
}
